window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-lead-pipeline.html"]="<!-- Settings: Lead Pipeline Config -->\n<style>\n.lp-section{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:20px;margin-bottom:20px}\n.lp-section h3{font-size:15px;font-weight:600;margin-bottom:14px}\n.lp-stage-row{display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-bottom:6px;background:var(--card);cursor:grab;transition:background .15s}\n.lp-stage-row:active{cursor:grabbing;opacity:.7}\n.lp-stage-row .drag-handle{color:var(--muted);font-size:14px;cursor:grab;width:20px;text-align:center}\n.lp-stage-row .stage-icon{font-size:18px;width:28px;text-align:center}\n.lp-stage-row .stage-label{flex:1;font-size:13px;font-weight:500}\n.lp-stage-row .stage-key{font-size:11px;color:var(--muted);font-family:monospace;background:var(--bg);padding:2px 6px;border-radius:4px}\n.lp-stage-row .stage-color{width:28px;height:28px;border-radius:6px;border:2px solid var(--border);cursor:pointer}\n.lp-stage-row .stage-terminal{font-size:11px;color:var(--muted);display:flex;align-items:center;gap:4px}\n.lp-stage-row .stage-terminal input{width:14px;height:14px}\n.lp-stage-row .btn-del{background:none;border:none;color:var(--danger);cursor:pointer;font-size:16px;padding:2px 6px;border-radius:4px}\n.lp-stage-row .btn-del:hover{background:rgba(239,68,68,.1)}\n.lp-add-row{display:flex;gap:8px;margin-top:10px;align-items:center}\n.lp-add-row input,.lp-add-row select{padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:13px}\n.lp-add-row input{flex:1}\n.lp-seg-wrap{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}\n.lp-seg{display:flex;align-items:center;gap:4px;padding:4px 10px;background:var(--bg);border:1px solid var(--border);border-radius:16px;font-size:13px}\n.lp-seg .btn-del-seg{background:none;border:none;color:var(--danger);cursor:pointer;font-size:14px;padding:0 2px}\n.lp-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:20px;padding-top:16px;border-top:1px solid var(--border)}\n.lp-preset-btns{display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap}\n.lp-preset-btns button{padding:6px 14px;border:1px solid var(--border);border-radius:8px;background:var(--card);font-size:12px;cursor:pointer}\n.lp-preset-btns button:hover{border-color:var(--accent);color:var(--accent)}\n.lp-preview{background:var(--bg);border-radius:var(--radius);padding:16px;margin-top:16px}\n.lp-preview-board{display:flex;gap:8px;overflow-x:auto}\n.lp-preview-col{min-width:100px;padding:8px;border-radius:8px;text-align:center;font-size:11px;font-weight:600}\n.emoji-pick-btn{width:36px;height:34px;font-size:18px;cursor:pointer;background:var(--card);border:1px solid var(--border);border-radius:6px;display:grid;place-items:center}\n.emoji-pick-btn:hover{border-color:var(--accent)}\n.emoji-popup{position:fixed;background:var(--card);border:1px solid var(--border);border-radius:10px;padding:8px;display:none;z-index:50;box-shadow:0 8px 24px rgba(0,0,0,.15);width:240px;max-height:200px;overflow-y:auto}\n.emoji-popup.open{display:block}\n.emoji-popup .emoji-grid{display:grid;grid-template-columns:repeat(8,1fr);gap:2px}\n.emoji-popup .emoji-grid span{font-size:18px;padding:4px;cursor:pointer;border-radius:4px;text-align:center}\n.emoji-popup .emoji-grid span:hover{background:var(--bg)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">🏢 Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">👥 Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">🔐 Peran</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">🏷️ Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">🕐 Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">🔄 Auto-Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">📥 Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">⏱ SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">⭐ CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">⚡ Macros</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">🎫 Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">💬 WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">📱 WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">🧩 Widget</div>\n    <div class=\"sn-title\">Prospek</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/lead-pipeline')\">💰 Pipeline Leads</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">🔗 Webhook</div>\n  </aside>\n  <div class=\"settings-content\">\n    <h2 style=\"font-size:18px;font-weight:700;margin-bottom:4px\">💰 Pipeline Leads</h2>\n    <p style=\"color:var(--muted);font-size:13px;margin-bottom:20px\">Konfigurasi stage pipeline dan segment leads. Perubahan langsung diterapkan ke halaman Prospuk.</p>\n\n    <!-- Presets -->\n    <div class=\"lp-section\">\n      <h3>🎨 Preset</h3>\n      <p style=\"font-size:12px;color:var(--muted);margin-bottom:10px\">Preset mengganti semua stage dan segment. Lead data yang sudah ada tetap tersimpan — status yang tidak cocok ditampilkan sebagai \"Unknown\".</p>\n      <div class=\"lp-preset-btns\" id=\"presetBtns\">\n        <button onclick=\"applyPreset('default')\">📋 Default (New→Won/Lost)</button>\n        <button onclick=\"applyPreset('clientA')\">🏢 Client A (Pending→Closed + Segments)</button>\n        <button onclick=\"applyPreset('simple')\">🎯 Simple (Cold→Hot→Won/Lost)</button>\n      </div>\n    </div>\n\n    <!-- Stages -->\n    <div class=\"lp-section\">\n      <h3>📊 Stage Pipeline</h3>\n      <p style=\"font-size:12px;color:var(--muted);margin-bottom:10px\">Drag untuk mengubah urutan. Kolom board di halaman Prospuk dirender sesuai urutan ini.</p>\n      <div id=\"stagesContainer\"></div>\n      <div class=\"lp-add-row\">\n        <input id=\"newStageLabel\" placeholder=\"Label stage baru...\">\n        <button class=\"emoji-pick-btn\" id=\"newStageIcon\" onclick=\"openEmojiPicker(this,'newStageIcon')\" type=\"button\">📌</button>\n        <input type=\"hidden\" id=\"newStageIconVal\" value=\"📌\">\n        <input type=\"color\" id=\"newStageColor\" value=\"#6b7280\" style=\"width:40px;height:34px;border:none;cursor:pointer\">\n        <label style=\"font-size:11px;display:flex;align-items:center;gap:4px\"><input type=\"checkbox\" id=\"newStageTerminal\"> Terminal</label>\n        <button class=\"btn primary\" onclick=\"addStage()\" style=\"padding:6px 12px\">+ Tambah</button>\n      </div>\n    </div>\n\n    <!-- Segments -->\n    <div class=\"lp-section\">\n      <h3>🏷 Segment Leads</h3>\n      <p style=\"font-size:12px;color:var(--muted);margin-bottom:10px\">Label untuk menggolongkan tipe lead (bukan stage pipeline). Lead bisa punya satu segment.</p>\n      <div class=\"lp-seg-wrap\" id=\"segmentsContainer\"></div>\n      <div class=\"lp-add-row\">\n        <input id=\"newSegment\" placeholder=\"Segment baru...\">\n        <button class=\"btn primary\" onclick=\"addSegment()\" style=\"padding:6px 12px\">+ Tambah</button>\n      </div>\n    </div>\n\n    <!-- Preview -->\n    <div class=\"lp-section\">\n      <h3>👁 Preview</h3>\n      <p style=\"font-size:12px;color:var(--muted);margin-bottom:10px\">Seperti ini tampilan board di halaman Prospuk:</p>\n      <div class=\"lp-preview\">\n        <div class=\"lp-preview-board\" id=\"previewBoard\"></div>\n      </div>\n    </div>\n\n    <!-- Actions -->\n    <div class=\"lp-actions\">\n      <button class=\"btn danger\" onclick=\"resetToDefault()\">🔄 Reset ke Default</button>\n      <button class=\"btn primary\" onclick=\"saveAndApply()\">💾 Simpan & Terapkan</button>\n    </div>\n  </div>\n  <div class=\"emoji-popup\" id=\"emojiPopup\" style=\"position:fixed\"></div>\n</div>\n\n<script>\n// ponytail: in-memory draft; only committed to DB.settings on save\nvar draftStages = [];\nvar draftSegments = [];\n\n// Presets\nvar PRESETS = {\n  default: {\n    stages: [\n      {key:'new',label:'New',color:'#3b82f6',icon:'🔵'},\n      {key:'contacted',label:'Contacted',color:'#8b5cf6',icon:'🟣'},\n      {key:'qualified',label:'Qualified',color:'#22c55e',icon:'🟢'},\n      {key:'proposal',label:'Proposal',color:'#eab308',icon:'🟡'},\n      {key:'negotiation',label:'Negotiation',color:'#f97316',icon:'🟠'},\n      {key:'won',label:'Won',color:'#16a34a',icon:'✅',isTerminal:true},\n      {key:'lost',label:'Lost',color:'#ef4444',icon:'❌',isTerminal:true},\n    ],\n    segments: ['Enterprise','SMB','Startup','VIP'],\n  },\n  clientA: {\n    stages: [\n      {key:'pending',label:'Pending',color:'#6b7280',icon:'⏳'},\n      {key:'cold',label:'Cold',color:'#3b82f6',icon:'🧊'},\n      {key:'hot',label:'Hot',color:'#ef4444',icon:'🔥'},\n      {key:'closed',label:'Closed',color:'#22c55e',icon:'✅',isTerminal:true},\n    ],\n    segments: ['Akuisisi','Scale up','Reaktivasi'],\n  },\n  simple: {\n    stages: [\n      {key:'cold',label:'Cold',color:'#3b82f6',icon:'🧊'},\n      {key:'hot',label:'Hot',color:'#ef4444',icon:'🔥'},\n      {key:'won',label:'Won',color:'#16a34a',icon:'✅',isTerminal:true},\n      {key:'lost',label:'Lost',color:'#ef4444',icon:'❌',isTerminal:true},\n    ],\n    segments: ['Baru','Repeat','VIP'],\n  },\n};\n\nfunction makeKey(label){\n  return label.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');\n}\n\nfunction renderStages(){\n  const c=document.getElementById('stagesContainer');\n  c.innerHTML=draftStages.map((s,i)=>`\n    <div class=\"lp-stage-row\" draggable=\"true\" data-idx=\"${i}\"\n         ondragstart=\"lpDragStart(event,${i})\" ondragover=\"lpDragOver(event)\" ondrop=\"lpDrop(event,${i})\">\n      <span class=\"drag-handle\">⠿</span>\n      <span class=\"stage-icon\" style=\"cursor:pointer\" onclick=\"openEmojiPicker(this,'stage',${i})\">${s.icon}</span>\n      <input class=\"stage-label\" value=\"${s.label}\" style=\"border:1px solid var(--border);border-radius:4px;padding:2px 6px;font-size:13px;width:120px\" onchange=\"updateStage(${i},'label',this.value)\">\n      <span class=\"stage-key\">${s.key}</span>\n      <input type=\"color\" class=\"stage-color\" value=\"${s.color}\" onchange=\"updateStage(${i},'color',this.value)\">\n      <label class=\"stage-terminal\"><input type=\"checkbox\" ${s.isTerminal?'checked':''} onchange=\"updateStage(${i},'isTerminal',this.checked)\"> Terminal</label>\n      <button class=\"btn-del\" onclick=\"removeStage(${i})\" title=\"Hapus\">✕</button>\n    </div>\n  `).join('');\n  renderPreview();\n}\n\nfunction renderSegments(){\n  const c=document.getElementById('segmentsContainer');\n  c.innerHTML=draftSegments.map((s,i)=>`\n    <span class=\"lp-seg\">${s} <button class=\"btn-del-seg\" onclick=\"removeSegment(${i})\">✕</button></span>\n  `).join('')||'<span style=\"color:var(--muted);font-size:13px\">Belum ada segment</span>';\n}\n\nfunction renderPreview(){\n  const b=document.getElementById('previewBoard');\n  b.innerHTML=draftStages.map(s=>`\n    <div class=\"lp-preview-col\" style=\"background:${s.color}22;color:${s.color};border:1px solid ${s.color}44\">${s.icon} ${s.label}</div>\n  `).join('');\n}\n\n// Stage CRUD\nfunction addStage(){\n  const lbl=document.getElementById('newStageLabel').value.trim();\n  if(!lbl)return;\n  const icon=document.getElementById('newStageIconVal').value||'📌';\n  const color=document.getElementById('newStageColor').value;\n  const isTerminal=document.getElementById('newStageTerminal').checked;\n  const key=makeKey(lbl);\n  if(draftStages.some(s=>s.key===key)){showToast('Key \"'+key+'\" sudah ada');return}\n  draftStages.push({key,label:lbl,color,icon,isTerminal});\n  document.getElementById('newStageLabel').value='';\n  document.getElementById('newStageTerminal').checked=false;\n  renderStages();\n}\nfunction updateStage(i,field,val){\n  draftStages[i][field]=val;\n  if(field==='label')draftStages[i].key=makeKey(val);\n  renderStages();\n}\nfunction removeStage(i){\n  const s=draftStages[i];\n  const count=(DB.leads||[]).filter(l=>l.status===s.key).length;\n  if(count>0&&!confirm(`${count} lead berstatus \"${s.label}\". Tetap hapus? Lead akan jadi \"Unknown\".`))return;\n  draftStages.splice(i,1);\n  renderStages();\n}\n\n// Segment CRUD\nfunction addSegment(){\n  const v=document.getElementById('newSegment').value.trim();\n  if(!v||draftSegments.includes(v))return;\n  draftSegments.push(v);\n  document.getElementById('newSegment').value='';\n  renderSegments();\n}\nfunction removeSegment(i){\n  draftSegments.splice(i,1);\n  renderSegments();\n}\n\n// Drag-drop reorder\nvar lpDragIdx=-1;\nfunction lpDragStart(e,i){lpDragIdx=i;e.dataTransfer.effectAllowed='move'}\nfunction lpDragOver(e){e.preventDefault();e.dataTransfer.dropEffect='move'}\nfunction lpDrop(e,i){\n  e.preventDefault();\n  if(lpDragIdx<0||lpDragIdx===i)return;\n  const item=draftStages.splice(lpDragIdx,1)[0];\n  draftStages.splice(i,0,item);\n  lpDragIdx=-1;\n  renderStages();\n}\n\n// Presets\nfunction applyPreset(name){\n  const p=PRESETS[name];\n  if(!p)return;\n  if(!confirm('Ganti semua stage & segment dengan preset \"'+name+'\"?'))return;\n  draftStages=JSON.parse(JSON.stringify(p.stages));\n  draftSegments=[...p.segments];\n  renderStages();\n  renderSegments();\n  showToast('Preset \"'+name+'\" diterapkan (belum disimpan)');\n}\n\nfunction resetToDefault(){\n  if(!confirm('Reset ke default? Semua perubahan hilang.'))return;\n  draftStages=JSON.parse(JSON.stringify(PRESETS.default.stages));\n  draftSegments=[...PRESETS.default.segments];\n  renderStages();\n  renderSegments();\n  saveAndApply();\n}\n\nfunction saveAndApply(){\n  // ponytail: remap lead.status by stage POSITION so leads never orphan when keys change.\n  // old stage#i -> new stage#i; overflow clamps to last new stage.\n  var oldKeys=(DB.settings.leadStages||[]).map(s=>s.key);\n  var newKeys=draftStages.map(s=>s.key);\n  if(oldKeys.length && newKeys.length && oldKeys.join()!==newKeys.join()){\n    (DB.leads||[]).forEach(function(l){\n      var i=oldKeys.indexOf(l.status);\n      if(i<0)i=0; // unknown status -> first stage\n      l.status=newKeys[Math.min(i,newKeys.length-1)];\n    });\n  }\n  DB.settings.leadStages=draftStages;\n  DB.settings.leadSegments=draftSegments;\n  saveDB();\n  showToast('Pipeline leads disimpan! Halaman Prospek akan menggunakan konfigurasi baru.');\n}\n\n// Init\nfunction renderSettingsLeadPipeline(){\n  draftStages=JSON.parse(JSON.stringify(DB.settings.leadStages||PRESETS.default.stages));\n  draftSegments=[...(DB.settings.leadSegments||PRESETS.default.segments)];\n  renderStages();\n  renderSegments();\n}\n\n// === EMOJI PICKER ===\nvar EMOJI_LIST=['🔵','🟣','🟢','🟡','🟠','✅','❌','📌','💰','🔥','🧊','⏳','⭐','🎯','💎','📊','🏷','🚀','💼','📈','🔔','📌','⚡','🎪','🏆','💜','🔴','🟤','🩷','🩵','🖤','🩶'];\nvar _emojiTarget=null; // {type:'new'|'stage', idx:N}\n\nfunction openEmojiPicker(el,type,idx){\n  closeEmojiPicker();\n  _emojiTarget={type,idx};\n  var popup=document.getElementById('emojiPopup');\n  popup.innerHTML='<div class=\"emoji-grid\">'+EMOJI_LIST.map(e=>'<span onclick=\"pickEmoji(\\''+e+'\\')\">'+e+'</span>').join('')+'</div>';\n  var rect=el.getBoundingClientRect();\n  var left=rect.left;\n  if(left+240>window.innerWidth)left=window.innerWidth-248;\n  popup.style.top=(rect.bottom+4)+'px';\n  popup.style.left=Math.max(0,left)+'px';\n  popup.classList.add('open');\n  setTimeout(()=>document.addEventListener('click',_emojiOutsideClick),0);\n}\nfunction _emojiOutsideClick(e){\n  if(!document.getElementById('emojiPopup').contains(e.target))closeEmojiPicker();\n}\nfunction closeEmojiPicker(){\n  document.getElementById('emojiPopup').classList.remove('open');\n  document.removeEventListener('click',_emojiOutsideClick);\n  _emojiTarget=null;\n}\nfunction pickEmoji(emoji){\n  if(!_emojiTarget){closeEmojiPicker();return}\n  if(_emojiTarget.type==='new'){\n    document.getElementById('newStageIcon').textContent=emoji;\n    document.getElementById('newStageIconVal').value=emoji;\n  }else{\n    draftStages[_emojiTarget.idx].icon=emoji;\n    renderStages();\n  }\n  closeEmojiPicker();\n}\n\nrenderSettingsLeadPipeline();\n</script>\n";
